WITH base AS (SELECT id, customer_id, order_date, status, channel, amount, discount, COALESCE(shipping_fee, 0) AS shipping_fee_filled FROM orders WHERE order_date > TO_DATE('2023-07-15') AND order_date < '2023-07-01') SELECT id, customer_id, order_date, status, channel, shipping_fee_filled FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, channel ORDER BY discount, id) AS dedup_rank FROM base) t WHERE dedup_rank = 1
